import { test, expect, Page } from '@playwright/test';

test.describe('Restore Archived Record', () => {
  let page: Page;

  test.beforeEach(async ({ browser }) => {
    page = await browser.newPage();
    await page.goto('http://localhost:3000');

    // Login if required
    const loginButton = page.getByRole('button', { name: /login/i });
    if (await loginButton.isVisible()) {
      await loginButton.click();
      await page.getByLabel(/email/i).fill('test@example.com');
      await page.getByLabel(/password/i).fill('password123');
      await page.getByRole('button', { name: /submit/i }).click();
      await page.waitForURL('**/dashboard');
    }
  });

  test('should display archived records in the archive section', async () => {
    // Navigate to records section
    await page.getByRole('link', { name: /records/i }).click();
    await page.waitForURL('**/records');

    // Navigate to archive section
    await page.getByRole('button', { name: /archive/i }).click();
    await page.waitForLoadState('networkidle');

    // Verify archived records are displayed
    const archivedRecordsList = page.getByRole('list', { name: /archived records/i });
    await expect(archivedRecordsList).toBeVisible();

    // Verify at least one archived record exists
    const archivedRecords = page.getByRole('listitem');
    const count = await archivedRecords.count();
    expect(count).toBeGreaterThan(0);
  });

  test('should restore a single archived record', async () => {
    // Navigate to records section
    await page.getByRole('link', { name: /records/i }).click();
    await page.waitForURL('**/records');

    // Navigate to archive section
    await page.getByRole('button', { name: /archive/i }).click();
    await page.waitForLoadState('networkidle');

    // Get the first archived record
    const firstRecord = page.getByRole('listitem').first();
    const recordName = await firstRecord.getByRole('heading').textContent();

    // Click on the record to open details
    await firstRecord.click();
    await page.waitForLoadState('networkidle');

    // Verify record details are displayed
    const recordTitle = page.getByRole('heading', { name: recordName || '' });
    await expect(recordTitle).toBeVisible();

    // Click restore button
    const restoreButton = page.getByRole('button', { name: /restore/i });
    await expect(restoreButton).toBeVisible();
    await restoreButton.click();

    // Verify confirmation dialog appears
    const confirmDialog = page.getByRole('dialog', { name: /confirm/i });
    await expect(confirmDialog).toBeVisible();

    // Confirm restoration
    const confirmButton = page.getByRole('button', { name: /confirm|yes|restore/i }).last();
    await confirmButton.click();

    // Wait for success message
    const successMessage = page.getByText(/restored successfully|record restored/i);
    await expect(successMessage).toBeVisible();

    // Verify we're back at archive list
    await page.waitForURL('**/records/archive');

    // Verify the record is no longer in the archive list
    const archivedRecords = page.getByRole('listitem');
    const recordStillExists = await archivedRecords.filter({ hasText: recordName || '' }).count();
    expect(recordStillExists).toBe(0);
  });

